import { Composition, Still, getStaticFiles, staticFile } from "remotion";
import { FPS, HEIGHT, WIDTH } from "../films/intro/manifest";
import { IntroFilm } from "./films/intro/IntroFilm";
import { THUMB_HEIGHT, THUMB_WIDTH, Thumbnail } from "./films/intro/Thumbnail";
import type { NarrationManifest } from "./films/intro/durations";
import { totalDuration } from "./films/intro/durations";
import type { FilmData } from "./films/intro/scenes/RecordedScene";
import type { ApplyTranscript } from "./films/intro/scenes/TerminalScene";

/**
 * Narration manifest is a generated file (gitignored), so it is loaded at
 * composition-metadata time rather than imported: a fresh clone renders the
 * placeholder cut with planned durations, and `npm run narrate` upgrades the
 * same composition to exact audio timing with no code change.
 */
const loadNarration = async (): Promise<NarrationManifest | null> => {
  const exists = getStaticFiles().some((f) => f.name === "narration/manifest.json");
  if (!exists) {
    return null;
  }
  const res = await fetch(staticFile("narration/manifest.json"));
  return (await res.json()) as NarrationManifest;
};

/** Presenter clips that exist on disk (generated by scripts/presenter.mjs). */
const presenterScenes = (): string[] =>
  getStaticFiles()
    .filter((f) => f.name.startsWith("presenter/") && f.name.endsWith(".mp4"))
    .map((f) => f.name.slice("presenter/".length, -".mp4".length));

/**
 * Captured footage and staged film data (assets/recordings/, gitignored),
 * loaded with the same degrade-to-placeholder contract as narration: a
 * missing asset renders a slate, never a broken frame.
 */
const loadFilmData = async (): Promise<FilmData> => {
  const files = getStaticFiles();
  const has = (name: string) => files.some((f) => f.name === name);
  const text = async (name: string) => (await fetch(staticFile(name))).text();

  const recordedShots = files
    .filter((f) => f.name.startsWith("recordings/") && f.name.endsWith(".webm"))
    .map((f) => f.name.slice("recordings/".length, -".webm".length));
  const agentYaml = has("recordings/s3b-agent-yaml.txt") ? await text("recordings/s3b-agent-yaml.txt") : null;
  const transcript = has("recordings/s3e-apply-transcript.json")
    ? ((await (await fetch(staticFile("recordings/s3e-apply-transcript.json"))).json()) as ApplyTranscript)
    : null;
  return { recordedShots, agentYaml, transcript };
};

export const Root = () => (
  <>
    <Composition
      id="IntroToStigmer"
      component={IntroFilm}
      width={WIDTH}
      height={HEIGHT}
      fps={FPS}
      defaultProps={{
        narration: null,
        presenterScenes: [],
        filmData: { recordedShots: [], agentYaml: null, transcript: null },
        hasMusic: false,
      }}
      calculateMetadata={async () => {
        const narration = await loadNarration();
        return {
          durationInFrames: totalDuration(narration),
          props: {
            narration,
            presenterScenes: presenterScenes(),
            filmData: await loadFilmData(),
            // Same degrade contract as every asset: no bed file, no bed.
            hasMusic: getStaticFiles().some((f) => f.name === "music/bed.mp3"),
          },
        };
      }}
    />
    {/* The film's YouTube thumbnail (see Thumbnail.tsx for the doctrine). */}
    <Still
      id="Thumbnail"
      component={Thumbnail}
      width={THUMB_WIDTH}
      height={THUMB_HEIGHT}
      defaultProps={{ hasPresenter: false }}
      calculateMetadata={async ({ props }) => ({
        props: {
          ...props,
          // Same degrade contract as the film: no clip, brand-only layout.
          hasPresenter: getStaticFiles().some((f) => f.name === "presenter/s6-close.mp4"),
        },
      })}
    />
  </>
);
